edges = [(0,1),(1,2),(2,3),(3,4),(0,4),
         (0,5),(1,6),(2,7),(3,8),(4,9),
         (5,7),(7,9),(6,9),(6,8),(5,8)]
n = 10
adj = {i:set() for i in range(n)}
for u,v in edges:
    adj[u].add(v); adj[v].add(u)

# triangle-free?
for a in range(n):
    for b in adj[a]:
        for c in adj[b]:
            if c!=a and c in adj[a]:
                print("triangle", a,b,c)

# maximal?
for u in range(n):
    for v in range(u+1,n):
        if v not in adj[u]:
            # check adding creates triangle
            common = adj[u] & adj[v]
            if not common:
                print("can add", u,v)
print("done, edges:", len(edges))
